// src/utils/exportImport.js
export const exportToJSON = (ideas, tasks) => {
  const exportData = {
    version: "1.0.0",
    exportDate: new Date().toISOString(),
    appName: "Woorkzi",
    data: { ideas, tasks }
  };

  const dataStr = JSON.stringify(exportData, null, 2);
  const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
  const exportFileDefaultName = `woorkzi_backup_${new Date().toISOString().slice(0,10)}.json`;
  
  const linkElement = document.createElement('a');
  linkElement.setAttribute('href', dataUri);
  linkElement.setAttribute('download', exportFileDefaultName);
  linkElement.click();
  
  return { success: true, filename: exportFileDefaultName };
};

export const exportToCSV = (ideas) => {
  const headers = ['ID', 'Başlık', 'Açıklama', 'Kategori', 'Durum', 'Öncelik'];
  const csvContent = [
    headers.join(','),
    ...ideas.map(idea => [
      idea.id,
      `"${idea.title}"`,
      `"${idea.description}"`,
      idea.category,
      idea.status,
      idea.priority
    ].join(','))
  ].join('\n');

  const dataUri = 'data:text/csv;charset=utf-8,\ufeff' + encodeURIComponent(csvContent);
  const exportFileDefaultName = `woorkzi_fikirler_${new Date().toISOString().slice(0,10)}.csv`;
  
  const linkElement = document.createElement('a');
  linkElement.setAttribute('href', dataUri);
  linkElement.setAttribute('download', exportFileDefaultName);
  linkElement.click();
  
  return { success: true, filename: exportFileDefaultName };
};

export const importFromJSON = (file) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const importData = JSON.parse(e.target.result);
        resolve({ success: true, data: importData.data });
      } catch (error) {
        reject({ success: false, error: error.message });
      }
    };
    reader.readAsText(file);
  });
};

export const validateImportData = (data) => {
  return { isValid: true, errors: [] };
};

export const generateStats = (ideas, tasks) => {
  return {
    totalIdeas: ideas.length,
    totalTasks: tasks.length,
    completedIdeas: ideas.filter(i => i.status === 'completed').length,
    avgProgress: Math.round(ideas.reduce((sum, idea) => sum + idea.completionPercentage, 0) / ideas.length)
  };
};
